import time

def retry(max_attempts, delay, exceptions):
    """
    Decorador para reintentar funciones fallidas.

    Parámetros:
    - max_attempts (int): Número máximo de intentos (incluye el primer intento).
    - delay (float): Tiempo de espera entre reintentos en segundos.
    - exceptions (tuple): Tipos de excepción que deben desencadenar reintentos.

    Ejemplo:
    @retry(max_attempts=3, delay=1.0, exceptions=(IOError, TimeoutError))
    def fetch_data(url):
        ...
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            last_exception = None
            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    last_exception = e
                    # Esperar solo si no es el último intento
                    if attempt < max_attempts - 1:
                        time.sleep(delay)
            # Si se agotan los intentos, lanzar la última excepción
            raise last_exception
        return wrapper
    return decorator
